from pathlib import Path
p=Path('src/FreshFood-API/tests/postgres/prerequisites.sql');p.write_text('''-- Minimal integration fixture reflecting the required approved catalog columns.
-- Not a replacement for the full project schema or a production bootstrap migration.
CREATE TABLE customers(customer_id BIGINT PRIMARY KEY,full_name TEXT);
CREATE TABLE staff_accounts(staff_id INT PRIMARY KEY);
CREATE TABLE customer_addresses(address_id BIGINT PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES customers,recipient_name TEXT,recipient_phone TEXT,street_address TEXT,latitude NUMERIC,longitude NUMERIC,is_default BOOLEAN DEFAULT FALSE);
CREATE TABLE products(product_id BIGINT PRIMARY KEY,product_name TEXT,unit_of_measure TEXT,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE batch_inventory(batch_id BIGINT PRIMARY KEY,product_id BIGINT REFERENCES products,expiry_date DATE NOT NULL,current_stock INT NOT NULL,reserved_stock INT NOT NULL DEFAULT 0,retail_price NUMERIC(18,0) NOT NULL,discount_rate NUMERIC(5,2) NOT NULL DEFAULT 0,sale_status TEXT NOT NULL DEFAULT 'ACTIVE',CHECK(reserved_stock>=0 AND current_stock>=reserved_stock));
CREATE TABLE carts(cart_id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers,session_id TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX fixture_customer_cart ON carts(customer_id) WHERE customer_id IS NOT NULL;
CREATE TABLE cart_items(cart_item_id BIGSERIAL PRIMARY KEY,cart_id BIGINT REFERENCES carts,product_id BIGINT REFERENCES products,quantity INT NOT NULL CHECK(quantity>0),added_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,UNIQUE(cart_id,product_id));
CREATE TABLE orders(order_id BIGSERIAL PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,customer_id BIGINT NOT NULL REFERENCES customers,delivery_address_id BIGINT NOT NULL REFERENCES customer_addresses,order_date TIMESTAMPTZ NOT NULL,sub_total NUMERIC(18,0) NOT NULL,delivery_distance NUMERIC(5,2) NOT NULL,shipping_fee NUMERIC(18,0) NOT NULL,total_amount NUMERIC(18,0) NOT NULL,payment_method TEXT NOT NULL CHECK(payment_method IN ('COD','VIETQR')),payment_status TEXT NOT NULL CHECK(payment_status IN ('UNPAID','PAID','PARTIALLY_REFUNDED','REFUNDED')),order_status TEXT NOT NULL CHECK(order_status IN ('PENDING_UNPAID','PENDING_PAID','CONFIRMED','PACKING','SHIPPING','DELIVERED','CANCELLED','DELIVERY_FAILED','RETURNED')),is_first_order BOOLEAN NOT NULL,phone_confirmation_status TEXT NOT NULL CHECK(phone_confirmation_status IN ('NOT_CONTACTED','CONFIRMED','UNCONFIRMED')),cancellation_reason TEXT);
CREATE TABLE order_details(order_detail_id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders,batch_id BIGINT NOT NULL REFERENCES batch_inventory,quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(18,0),discount_amount NUMERIC(18,0),line_total NUMERIC(18,0));
CREATE TABLE audit_logs(log_id BIGSERIAL PRIMARY KEY,staff_id INT REFERENCES staff_accounts,action_type TEXT NOT NULL CHECK(action_type IN ('INSERT','UPDATE','DELETE','LOGIN','REVOKE')),entity_name TEXT NOT NULL,record_identifier TEXT NOT NULL,old_values JSONB,new_values JSONB,ip_address VARCHAR(45),timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO customers VALUES(7,'Test customer'),(8,'Other test customer');
INSERT INTO staff_accounts VALUES(1);
INSERT INTO customer_addresses VALUES(2,7,'Tester','0901234567','Test street',10,106,TRUE),(3,8,'Other','0901234568','Other test street',10,106,TRUE);
INSERT INTO products VALUES(1,'Organic greens','pack',TRUE);
INSERT INTO batch_inventory VALUES(1,1,'2099-01-01',10,0,10000,0,'ACTIVE');
INSERT INTO carts(customer_id) VALUES(7),(8);
INSERT INTO cart_items(cart_id,product_id,quantity) SELECT cart_id,1,3 FROM carts;
INSERT INTO audit_logs(staff_id,action_type,entity_name,record_identifier) VALUES(1,'UPDATE','orders','legacy-staff'),(NULL,'UPDATE','orders','legacy-system');
''',encoding='utf-8')
Path('src/FreshFood-API/tests/postgres/storage.test.js').write_text('''import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {PGlite} from '@electric-sql/pglite';
import {createRequestScope} from '../../composition.js';
const up=readFileSync(new URL('../../../FreshFood-DB/migrations/20261102_001_order_consistency.up.sql',import.meta.url),'utf8');
const down=readFileSync(new URL('../../../FreshFood-DB/migrations/20261102_001_order_consistency.down.sql',import.meta.url),'utf8');
const base=readFileSync(new URL('./prerequisites.sql',import.meta.url),'utf8');
const request={AddressId:'2',PaymentMethod:'Cod',CheckoutReference:'checkout-1',IdempotencyKey:'event-1'};
async function fixture(t){
 const db=new PGlite();await db.exec(base);await db.exec(up);t.after(()=>db.close());
 // PGlite has one connection. Serialize complete transactions and individual external reads;
 // this tests real SQL/rollback/constraints, not multi-connection PostgreSQL lock contention.
 let queue=Promise.resolve();async function acquire(){let done;const prev=queue;queue=new Promise(r=>done=r);await prev;return done;}
 const notifications=[];let fault;
 function scope(customerId='7'){
  let release;
  const connection={async QueryAsync(sql,parameters=[],signal){signal?.throwIfAborted();
   if(sql==='BEGIN'){release=await acquire();try{return await db.query(sql);}catch(e){release();release=undefined;throw e;}}
   if(sql==='COMMIT'||sql==='ROLLBACK'){try{return await db.query(sql);}finally{release?.();release=undefined;}}
   const local=release?undefined:await acquire();try{if(fault?.(sql))throw new Error('injected storage failure');return await db.query(sql,parameters);}finally{local?.();}
  }};
  const transport={async SendAsync(key,payload){if(key==='maps:distance')return 1;if(key==='notifications:publish'){notifications.push(payload);return;}throw new Error('Live gateway disabled');}};
  return createRequestScope({connection,principal:{CustomerId:customerId},transport});
 }
 return {db,scope,notifications,setFault(f){fault=f;},async scalar(sql){return Object.values((await db.query(sql)).rows[0])[0];},async place(s=scope(),r=request){return s.Resolve('CheckoutController').PlaceOrderAsync(r);}};
}
test('migration preserves legacy STAFF/SYSTEM audit and validates CUSTOMER identity',async t=>{const f=await fixture(t);let rows=(await f.db.query('SELECT actor_type FROM audit_logs ORDER BY log_id')).rows;assert.deepEqual(rows.map(r=>r.actor_type),['STAFF','SYSTEM']);await f.db.query("INSERT INTO audit_logs(customer_id,action_type,entity_name,record_identifier) VALUES(7,'UPDATE','orders','test')");assert.equal(await f.scalar("SELECT actor_type FROM audit_logs WHERE customer_id=7"),'CUSTOMER');await assert.rejects(f.db.query("INSERT INTO audit_logs(staff_id,customer_id,action_type,entity_name,record_identifier) VALUES(1,7,'UPDATE','orders','bad')"),e=>e.code==='23514');await assert.rejects(f.db.query("INSERT INTO audit_logs(customer_id,action_type,entity_name,record_identifier) VALUES(999,'UPDATE','orders','bad')"),e=>e.code==='23503');});
test('unused migration can roll back without changing legacy audit entries',async t=>{const f=await fixture(t);await f.db.exec(down);assert.equal(Number(await f.scalar('SELECT count(*) FROM audit_logs')),2);assert.equal(await f.scalar("SELECT to_regclass('checkout_idempotency')"),null);await f.db.exec(up);assert.equal(Number(await f.scalar("SELECT count(*) FROM audit_logs WHERE actor_type='SYSTEM'")),1);});
test('SQL checkout retry replays the original response after cart clear without duplicate effects',async t=>{const f=await fixture(t);const first=await f.place();const second=await f.place();assert.deepEqual(second,first);assert.equal(Number(await f.scalar('SELECT count(*) FROM orders')),1);assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),3);assert.equal(Number(await f.scalar('SELECT count(*) FROM order_transition_events')),3);assert.equal(Number(await f.scalar('SELECT count(*) FROM order_transition_events WHERE order_id IS NOT NULL')),3);assert.equal(Number(await f.scalar('SELECT count(*) FROM checkout_idempotency WHERE response IS NOT NULL')),1);assert.equal(f.notifications.length,1);assert.equal(await f.scalar('SELECT phone_confirmation_status FROM orders'),'NOT_CONTACTED');});
test('same idempotency key with changed body is rejected instead of creating another order',async t=>{const f=await fixture(t);await f.place();await assert.rejects(f.place(f.scope(),{...request,CheckoutReference:'different'}),{code:'IDEMPOTENCY_KEY_REUSED'});assert.equal(Number(await f.scalar('SELECT count(*) FROM orders')),1);});
test('same checkout reference with a different key is rejected',async t=>{const f=await fixture(t);await f.place();await assert.rejects(f.place(f.scope(),{...request,IdempotencyKey:'different'}),{code:'CHECKOUT_REFERENCE_REUSED'});assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),3);});
test('customer-scoped keys/references cannot collide across customers',async t=>{const f=await fixture(t);const a=await f.place();const b=await f.place(f.scope('8'),{...request,AddressId:'3'});assert.notEqual(a.OrderId,b.OrderId);assert.equal(Number(await f.scalar('SELECT count(*) FROM orders')),2);assert.equal(Number(await f.scalar('SELECT count(DISTINCT aggregate_key) FROM order_transition_events')),2);assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),6);});
test('failed checkout rolls back claim, events, order, stock and cart as one unit and allows retry',async t=>{const f=await fixture(t);f.setFault(sql=>sql.startsWith('DELETE FROM cart_items'));await assert.rejects(f.place(),/injected/);for(const table of ['orders','order_transition_events','checkout_idempotency'])assert.equal(Number(await f.scalar('SELECT count(*) FROM '+table)),0);assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),0);assert.equal(Number(await f.scalar('SELECT quantity FROM cart_items WHERE cart_id=1')),3);assert.equal(f.notifications.length,0);f.setFault(undefined);await f.place();assert.equal(Number(await f.scalar('SELECT count(*) FROM orders')),1);});
test('cancellation releases once, audits customer once and preserves original reason on retry',async t=>{const f=await fixture(t);const order=await f.place();const cancel=()=>f.scope().Resolve('MyOrdersController').CancelOrderAsync({OrderId:order.OrderId,Reason:'Changed plans'});assert.equal((await cancel()).MessageCode,'ORDER_CANCELLED');assert.equal((await cancel()).MessageCode,'ORDER_ALREADY_CANCELLED');assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),0);assert.equal(Number(await f.scalar("SELECT count(*) FROM order_transition_events WHERE transition_id='T08u'")),1);const audit=(await f.db.query("SELECT * FROM audit_logs WHERE customer_id=7")).rows;assert.equal(audit.length,1);assert.equal(audit[0].actor_type,'CUSTOMER');assert.equal(audit[0].staff_id,null);assert.equal(audit[0].new_values.cancellation_reason,'Changed plans');assert.equal(f.notifications.length,2);});
test('another customer cannot cancel or append customer audit for an unowned order',async t=>{const f=await fixture(t);const order=await f.place();await assert.rejects(f.scope('8').Resolve('MyOrdersController').CancelOrderAsync({OrderId:order.OrderId,Reason:'Forged'}),{code:'NOT_FOUND'});assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),3);assert.equal(Number(await f.scalar('SELECT count(*) FROM audit_logs WHERE customer_id IS NOT NULL')),0);});
test('audit failure rolls back cancellation, event and released reservation, then retry succeeds',async t=>{const f=await fixture(t);const order=await f.place();f.setFault(sql=>sql.startsWith('INSERT INTO audit_logs'));const cancel=()=>f.scope().Resolve('MyOrdersController').CancelOrderAsync({OrderId:order.OrderId,Reason:'Changed plans'});await assert.rejects(cancel(),/injected/);assert.equal(await f.scalar('SELECT order_status FROM orders'),'PENDING_UNPAID');assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),3);assert.equal(Number(await f.scalar("SELECT count(*) FROM order_transition_events WHERE transition_id='T08u'")),0);f.setFault(undefined);await cancel();assert.equal(Number(await f.scalar('SELECT count(*) FROM audit_logs WHERE customer_id=7')),1);});
test('duplicate transition identity is rejected by unique storage independently of handler execution',async t=>{const f=await fixture(t);const scope=f.scope();const repository=scope.Resolve('IOrderLifecycleRepository');await scope.Resolve('IUnitOfWork').ExecuteAsync(async()=>{assert.equal(await repository.RecordEventOnceAsync('checkout:7:ref','event','I00'),true);assert.equal(await repository.RecordEventOnceAsync('checkout:7:ref','event','I00'),false);assert.equal(await repository.RecordEventOnceAsync('checkout:7:ref','event','T01u'),true);});assert.equal(Number(await f.scalar('SELECT count(*) FROM order_transition_events')),2);});
test('concurrent application retries serialize to one checkout on the embedded connection',async t=>{const f=await fixture(t);const [a,b]=await Promise.all([f.place(f.scope()),f.place(f.scope())]);assert.deepEqual(a,b);assert.equal(Number(await f.scalar('SELECT count(*) FROM orders')),1);assert.equal(Number(await f.scalar('SELECT reserved_stock FROM batch_inventory')),3);});
test('rollback migration refuses to discard nonempty idempotency/audit history',async t=>{const f=await fixture(t);await f.place();await assert.rejects(f.db.exec(down),/Rollback refused/);await f.db.exec('ROLLBACK');assert.equal(Number(await f.scalar('SELECT count(*) FROM checkout_idempotency')),1);assert.notEqual(await f.scalar("SELECT to_regclass('order_transition_events')"),null);});
''',encoding='utf-8')
# Preserve timestamp precision for order_date; only actual LocalDate columns are date-only.
p=Path('src/FreshFood.Reposistory/Repository/Implements/sql.js');s=p.read_text().replace("k.endsWith('_date')&&v instanceof Date", "['expiry_date','manufacture_date'].includes(k)&&v instanceof Date");p.write_text(s,encoding='utf-8')
print('Created real SQL migration/repository integration tests on temporary embedded PostgreSQL')
